// Illustrative example, x402 V2. Decoded PAYMENT-REQUIRED. The scheme is not named in Cloudflare's post.
{
  "x402Version": 2,
  "resource": { "url": "https://publisher.example/api/article/42" },
  "accepts": [
    {
      "scheme": "<not named in the announcement>",
      "network": "eip155:8453",
      "amount": "1000",
      "asset": "<USDC contract on Base>",
      "payTo": "0x<seller address>",
      "maxTimeoutSeconds": 60
    }
  ]
}

// Illustrative example, cloudflare:402 network version 1.0.0. Decoded PAYMENT-REQUIRED.
{
  "x402Version": 2,
  "resource": { "url": "https://publisher.example/article", "mimeType": "text/html" },
  "accepts": [
    { "scheme": "batch-settlement", "network": "cloudflare:402", "amount": "1", "asset": "USD", "payTo": "merchant", "extra": { "version": "1.0.0" } }
  ],
  "extensions": {
    "http-message-signatures": {
      "info": { "registrationUrl": "<Cloudflare pay-per-crawl verification docs>", "signatureSchemes": ["ed25519"], "tags": ["web-bot-auth"] }
    }
  }
}
